package mining_threat_retreat_supervision.Mining_Threat_Retreat_Supervision

import org.sireum._
import art._
import mining_threat_retreat_supervision._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Outcome_Observation_Api {
  def id: Art.BridgeId
  def action_outcome_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var action_outcome: Mining_Threat_Retreat_Supervision.ActionOutcomeValue = $

  def put_action_outcome(value : Mining_Threat_Retreat_Supervision.ActionOutcomeValue) : Unit = {
    Contract(
      Modifies(action_outcome),
      Ensures(
        action_outcome == value
      )
    )
    Spec {
      action_outcome = value
    }

    Art.putValue(action_outcome_Id, Mining_Threat_Retreat_Supervision.ActionOutcomeValue_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Outcome_Observation_Initialization_Api (
  val id: Art.BridgeId,
  val action_outcome_Id : Art.PortId) extends Outcome_Observation_Api

@datatype class Outcome_Observation_Operational_Api (
  val id: Art.BridgeId,
  val action_outcome_Id : Art.PortId) extends Outcome_Observation_Api {

}
